// CSEC Physics practical companions for the existing interactive models.
// Each blueprint turns a simulation into a full experimental workflow with a student notebook.

const make = config => Object.freeze({
  ...config,
  apparatus: Object.freeze(config.apparatus || []),
  variables: config.variables ? Object.freeze({
    independent: config.variables.independent || '',
    dependent: config.variables.dependent || '',
    controls: Object.freeze(config.variables.controls || []),
  }) : null,
  method: Object.freeze(config.method || []),
  table: config.table ? Object.freeze({
    rows: config.table.rows || 5,
    columns: Object.freeze((config.table.columns || []).map(column => Object.freeze(column))),
  }) : null,
  graph: config.graph ? Object.freeze({ fitMode:'linear', ...config.graph }) : null,
  analysis: Object.freeze(config.analysis || []),
  errors: Object.freeze(config.errors || []),
  accuracy: Object.freeze(config.accuracy || []),
  safety: Object.freeze(config.safety || []),
  followUp: Object.freeze((config.followUp || []).map(item => Object.freeze(item))),
});

