export function physicsPracticalForInteractive(interactiveId) {
  return PHYSICS_PRACTICAL_BLUEPRINTS[String(interactiveId || '')] || null;
}

export function physicsPracticalStats() {
  const blueprints = Object.values(PHYSICS_PRACTICAL_BLUEPRINTS);
  return Object.freeze({
    practicals: blueprints.length,
    withGraphs: blueprints.filter(item => item.graph).length,
    topics: new Set(blueprints.map(item => item.topic)).size,
    sections: new Set(blueprints.map(item => item.topic?.[0])).size,
  });
}
